{
  "name": "NexusStats LoL Explorer",
  "description": "A comprehensive League of Legends player and esports statistics platform featuring real-time player search, match history, and professional tournament standings."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface PlayerSummary {
  name: string;
  tag: string;
  region: string;
  level: number;
  profileIconUrl: string;
  rank: {
    tier: string;
    rank: string;
    lp: number;
    wins: number;
    losses: number;
    winRate: number;
  };
  topChampions: Array<{
    name: string;
    level: number;
    points: number;
    iconUrl: string;
  }>;
}

export interface Participant {
  summonerName: string;
  championName: string;
  championIcon: string;
  role: string;
  kills: number;
  deaths: number;
  assists: number;
  cs: number;
  gold: number;
  damage: number;
  items: string[];
  teamId: number;
  win: boolean;
}

export interface Match {
  id: string;
  gameMode: string;
  duration: string;
  creationDate: string;
  isWin: boolean;
  participants: Participant[];
  teams: Array<{
    teamId: number;
    win: boolean;
    kills: number;
    gold: number;
    objectives: {
      baron: number;
      dragon: number;
      tower: number;
    };
  }>;
}

export interface EsportsMatch {
  id: string;
  league: string;
  teamA: {
    name: string;
    logo: string;
    score: number;
  };
  teamB: {
    name: string;
    logo: string;
    score: number;
  };
  status: 'upcoming' | 'live' | 'completed';
  timestamp: string;
  matchDetails?: Match;
}

export interface Standing {
  teamName: string;
  logo: string;
  wins: number;
  losses: number;
  rank: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { PlayerSummary, Match, EsportsMatch, Standing } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const geminiService = {
  async searchPlayer(name: string, region: string): Promise<PlayerSummary> {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Search for a League of Legends player named "${name}" in region "${region}". Generate a realistic profile.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            tag: { type: Type.STRING },
            region: { type: Type.STRING },
            level: { type: Type.NUMBER },
            profileIconUrl: { type: Type.STRING },
            rank: {
              type: Type.OBJECT,
              properties: {
                tier: { type: Type.STRING },
                rank: { type: Type.STRING },
                lp: { type: Type.NUMBER },
                wins: { type: Type.NUMBER },
                losses: { type: Type.NUMBER },
                winRate: { type: Type.NUMBER },
              },
              required: ["tier", "rank", "lp", "wins", "losses", "winRate"]
            },
            topChampions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  level: { type: Type.NUMBER },
                  points: { type: Type.NUMBER },
                  iconUrl: { type: Type.STRING },
                },
                required: ["name", "level", "points", "iconUrl"]
              }
            }
          },
          required: ["name", "tag", "region", "level", "profileIconUrl", "rank", "topChampions"]
        },
      },
    });

    return JSON.parse(response.text);
  },

  async getMatchHistory(playerName: string): Promise<Match[]> {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate 5 detailed recent League of Legends matches for ${playerName}.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              gameMode: { type: Type.STRING },
              duration: { type: Type.STRING },
              creationDate: { type: Type.STRING },
              isWin: { type: Type.BOOLEAN },
              participants: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    summonerName: { type: Type.STRING },
                    championName: { type: Type.STRING },
                    championIcon: { type: Type.STRING },
                    role: { type: Type.STRING },
                    kills: { type: Type.NUMBER },
                    deaths: { type: Type.NUMBER },
                    assists: { type: Type.NUMBER },
                    cs: { type: Type.NUMBER },
                    gold: { type: Type.NUMBER },
                    damage: { type: Type.NUMBER },
                    items: { type: Type.ARRAY, items: { type: Type.STRING } },
                    teamId: { type: Type.NUMBER },
                    win: { type: Type.BOOLEAN }
                  },
                  required: ["summonerName", "championName", "championIcon", "role", "kills", "deaths", "assists", "cs", "gold", "damage", "items", "teamId", "win"]
                }
              },
              teams: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    teamId: { type: Type.NUMBER },
                    win: { type: Type.BOOLEAN },
                    kills: { type: Type.NUMBER },
                    gold: { type: Type.NUMBER },
                    objectives: {
                      type: Type.OBJECT,
                      properties: {
                        baron: { type: Type.NUMBER },
                        dragon: { type: Type.NUMBER },
                        tower: { type: Type.NUMBER }
                      },
                      required: ["baron", "dragon", "tower"]
                    }
                  },
                  required: ["teamId", "win", "kills", "gold", "objectives"]
                }
              }
            },
            required: ["id", "gameMode", "duration", "creationDate", "isWin", "participants", "teams"]
          }
        },
      },
    });

    return JSON.parse(response.text);
  },

  async getEsportsData(): Promise<{ matches: EsportsMatch[]; standings: Standing[] }> {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: "Generate current League of Legends esports information including 4 matches (mix of live, upcoming, completed) and top 5 standings for a major league like LCK or LCS.",
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            matches: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  league: { type: Type.STRING },
                  teamA: {
                    type: Type.OBJECT,
                    properties: { name: { type: Type.STRING }, logo: { type: Type.STRING }, score: { type: Type.NUMBER } },
                    required: ["name", "logo", "score"]
                  },
                  teamB: {
                    type: Type.OBJECT,
                    properties: { name: { type: Type.STRING }, logo: { type: Type.STRING }, score: { type: Type.NUMBER } },
                    required: ["name", "logo", "score"]
                  },
                  status: { type: Type.STRING },
                  timestamp: { type: Type.STRING }
                },
                required: ["id", "league", "teamA", "teamB", "status", "timestamp"]
              }
            },
            standings: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  teamName: { type: Type.STRING },
                  logo: { type: Type.STRING },
                  wins: { type: Type.NUMBER },
                  losses: { type: Type.NUMBER },
                  rank: { type: Type.NUMBER }
                },
                required: ["teamName", "logo", "wins", "losses", "rank"]
              }
            }
          },
          required: ["matches", "standings"]
        },
      },
    });

    return JSON.parse(response.text);
  }
};

import React, { useState } from 'react';
import { REGIONS, Icons } from '../constants';

interface SearchBarProps {
  onSearch: (name: string, region: string) => void;
  isLoading?: boolean;
}

const SearchBar: React.FC<SearchBarProps> = ({ onSearch, isLoading }) => {
  const [name, setName] = useState('');
  const [region, setRegion] = useState('na');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim()) {
      onSearch(name.trim(), region);
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto">
      <form onSubmit={handleSubmit} className="relative group">
        <div className="flex flex-col md:flex-row gap-2 bg-[#0a1428]/80 p-2 border border-[#1e2328] rounded shadow-2xl backdrop-blur-md group-focus-within:border-[#c89b3c] transition-all">
          <div className="relative flex-grow">
             <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Search for a Summoner..."
              className="w-full bg-transparent text-white px-4 py-3 outline-none placeholder-gray-500 text-lg"
            />
          </div>

          <div className="flex gap-2">
            <select
              value={region}
              onChange={(e) => setRegion(e.target.value)}
              className="bg-[#1e2328] text-white px-4 py-2 border border-[#3c3c41] rounded focus:border-[#c89b3c] outline-none cursor-pointer hover:bg-[#2a2f35] transition-colors appearance-none pr-10 relative"
              style={{ backgroundImage: `url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>')`, backgroundRepeat: 'no-repeat', backgroundPosition: 'right 10px center' }}
            >
              {REGIONS.map((reg) => (
                <option key={reg.value} value={reg.value} className="bg-[#1e2328]">
                  {reg.label}
                </option>
              ))}
            </select>

            <button
              type="submit"
              disabled={isLoading}
              className={`flex items-center justify-center px-8 py-3 rounded font-bold uppercase tracking-wider transition-all shadow-lg ${
                isLoading 
                  ? 'bg-gray-700 text-gray-400 cursor-not-allowed' 
                  : 'bg-[#c8aa6e] hover:bg-[#c89b3c] text-[#0a1428]'
              }`}
            >
              {isLoading ? (
                <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <div className="flex items-center gap-2">
                  <Icons.Search />
                  <span>Search</span>
                </div>
              )}
            </button>
          </div>
        </div>

        {/* Subtle glow effect */}
        <div className="absolute -inset-0.5 bg-[#c8aa6e]/10 blur opacity-0 group-focus-within:opacity-100 transition duration-500 rounded pointer-events-none"></div>
      </form>
    </div>
  );
};

export default SearchBar;

import React, { useState } from 'react';
import { Match, Participant } from '../types';

interface MatchHistoryProps {
  matches: Match[];
}

const MatchHistory: React.FC<MatchHistoryProps> = ({ matches }) => {
  const [expandedMatchId, setExpandedMatchId] = useState<string | null>(null);

  const toggleMatch = (id: string) => {
    setExpandedMatchId(expandedMatchId === id ? null : id);
  };

  return (
    <div className="flex flex-col gap-4 mt-8">
      <div className="flex items-center justify-between px-2">
        <h2 className="text-xl font-bold text-white tracking-tight">Recent Matches</h2>
        <div className="flex gap-2">
          <button className="bg-[#1e2328] text-xs px-3 py-1 rounded border border-[#3c3c41] text-gray-300 hover:text-white">All</button>
          <button className="bg-[#1e2328] text-xs px-3 py-1 rounded border border-[#3c3c41] text-gray-300 hover:text-white">Ranked</button>
        </div>
      </div>

      {matches.map((match) => (
        <div key={match.id} className="flex flex-col border border-[#1e2328] rounded overflow-hidden">
          {/* Collapsed View */}
          <div 
            onClick={() => toggleMatch(match.id)}
            className={`flex flex-col md:flex-row items-center p-4 cursor-pointer transition-all hover:bg-[#1e2328]/50 border-l-4 ${
              match.isWin ? 'border-blue-500 bg-blue-500/5' : 'border-red-500 bg-red-500/5'
            }`}
          >
            <div className="flex items-center gap-4 w-full md:w-auto md:min-w-[150px]">
              <div className="flex flex-col">
                <span className={`font-bold text-sm ${match.isWin ? 'text-blue-400' : 'text-red-400'}`}>
                  {match.isWin ? 'Victory' : 'Defeat'}
                </span>
                <span className="text-gray-500 text-xs">{match.gameMode}</span>
                <span className="text-gray-500 text-[10px] mt-1">{match.creationDate}</span>
              </div>
            </div>

            <div className="flex items-center gap-4 flex-grow justify-start w-full md:w-auto mt-4 md:mt-0">
               {/* This is simplified to show first participant as "the player" for demo purposes */}
               <div className="relative">
                  <img 
                    src={match.participants[0].championIcon || `https://picsum.photos/seed/${match.participants[0].championName}/100/100`} 
                    alt="Champ" 
                    className="w-12 h-12 rounded border border-[#1e2328]"
                  />
                  <div className="absolute -bottom-1 -right-1 bg-[#1e2328] text-[8px] text-white px-1 rounded border border-gray-700">18</div>
               </div>

               <div className="flex flex-col">
                  <div className="text-white font-bold text-sm">
                    {match.participants[0].kills} / <span className="text-red-500">{match.participants[0].deaths}</span> / {match.participants[0].assists}
                  </div>
                  <div className="text-gray-400 text-xs">
                    {((match.participants[0].kills + match.participants[0].assists) / (match.participants[0].deaths || 1)).toFixed(2)} KDA
                  </div>
               </div>

               <div className="grid grid-cols-4 gap-0.5 ml-4">
                  {match.participants[0].items.slice(0, 6).map((item, i) => (
                    <div key={i} className="w-6 h-6 bg-[#0a1428] border border-gray-800 rounded-sm"></div>
                  ))}
               </div>
            </div>

            <div className="hidden lg:flex items-center gap-2 ml-4">
               <div className="flex flex-col gap-0.5">
                  {match.participants.slice(0, 5).map((p, i) => (
                    <div key={i} className="flex items-center gap-1">
                      <div className="w-4 h-4 rounded-sm bg-gray-800"></div>
                      <span className="text-[10px] text-gray-400 truncate w-20">{p.summonerName}</span>
                    </div>
                  ))}
               </div>
               <div className="flex flex-col gap-0.5">
                  {match.participants.slice(5, 10).map((p, i) => (
                    <div key={i} className="flex items-center gap-1">
                      <div className="w-4 h-4 rounded-sm bg-gray-800"></div>
                      <span className="text-[10px] text-gray-400 truncate w-20">{p.summonerName}</span>
                    </div>
                  ))}
               </div>
            </div>

            <div className="ml-auto">
               <svg 
                  className={`w-5 h-5 text-gray-500 transition-transform ${expandedMatchId === match.id ? 'rotate-180' : ''}`}
                  fill="none" stroke="currentColor" viewBox="0 0 24 24"
               >
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
               </svg>
            </div>
          </div>

          {/* Expanded View */}
          {expandedMatchId === match.id && (
            <div className="bg-[#0a1428] border-t border-[#1e2328] p-4 animate-fadeIn">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                 {/* Team 1 */}
                 <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between px-2 bg-blue-900/20 py-1 rounded">
                      <span className="text-blue-400 font-bold text-xs">BLUE TEAM</span>
                      <span className="text-gray-400 text-[10px]">Towers: {match.teams[0].objectives.tower} | Barons: {match.teams[0].objectives.baron}</span>
                    </div>
                    {match.participants.filter(p => p.teamId === 100).map((p, i) => (
                      <ScoreboardRow key={i} participant={p} />
                    ))}
                 </div>
                 {/* Team 2 */}
                 <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between px-2 bg-red-900/20 py-1 rounded">
                      <span className="text-red-400 font-bold text-xs">RED TEAM</span>
                      <span className="text-gray-400 text-[10px]">Towers: {match.teams[1].objectives.tower} | Barons: {match.teams[1].objectives.baron}</span>
                    </div>
                    {match.participants.filter(p => p.teamId === 200).map((p, i) => (
                      <ScoreboardRow key={i} participant={p} />
                    ))}
                 </div>
              </div>
            </div>
          )}
        </div>
      ))}
    </div>
  );
};

const ScoreboardRow: React.FC<{ participant: Participant }> = ({ participant }) => (
  <div className="flex items-center gap-2 p-1 hover:bg-[#1e2328] rounded transition-colors border border-transparent hover:border-[#3c3c41]">
    <div className="w-8 h-8 rounded-full bg-gray-800 overflow-hidden shrink-0">
       <img src={participant.championIcon || `https://picsum.photos/seed/${participant.championName}/50/50`} className="w-full h-full object-cover" alt="" />
    </div>
    <div className="flex flex-col w-24 shrink-0 overflow-hidden">
       <div className="text-[10px] text-white font-bold truncate">{participant.summonerName}</div>
       <div className="text-[8px] text-gray-500 uppercase">{participant.championName}</div>
    </div>
    <div className="flex-grow flex items-center gap-3">
       <div className="text-[10px] font-bold text-gray-300 w-16 text-center">
         {participant.kills}/{participant.deaths}/{participant.assists}
       </div>
       <div className="hidden sm:flex gap-0.5">
         {[1,2,3,4,5,6].map(i => <div key={i} className="w-4 h-4 bg-[#0a1428] border border-gray-800 rounded-sm"></div>)}
       </div>
    </div>
    <div className="text-[10px] text-gray-400 w-12 text-right">{participant.cs} CS</div>
  </div>
);

export default MatchHistory;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, useNavigate } from 'react-router-dom';
import Layout from './components/Layout';
import SearchBar from './components/SearchBar';
import PlayerStats from './components/PlayerStats';
import MatchHistory from './components/MatchHistory';
import EsportsSection from './components/EsportsSection';
import { geminiService } from './services/geminiService';
import { PlayerSummary, Match, EsportsMatch, Standing } from './types';

const HomePage = () => {
  const navigate = useNavigate();
  const [esportsData, setEsportsData] = useState<{ matches: EsportsMatch[]; standings: Standing[] } | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const data = await geminiService.getEsportsData();
        setEsportsData(data);
      } catch (err) {
        console.error("Failed to load esports data", err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const handleSearch = (name: string, region: string) => {
    navigate(`/profile/${region}/${name}`);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-12 md:py-24">
      <div className="text-center mb-16 relative">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-blue-600/10 blur-[120px] pointer-events-none rounded-full"></div>
        <h1 className="lol-font text-5xl md:text-7xl mb-4 text-[#c8aa6e] uppercase tracking-tighter drop-shadow-2xl">
          Evolve your Game
        </h1>
        <p className="text-gray-400 text-lg md:text-xl max-w-2xl mx-auto font-light">
          Analyze summoner performance, track your progress, and stay updated with the global League of Legends esports scene.
        </p>
      </div>

      <SearchBar onSearch={handleSearch} />

      <div className="mt-24">
        {loading ? (
          <div className="flex flex-col items-center justify-center py-20 space-y-4">
             <div className="w-12 h-12 border-4 border-[#c8aa6e] border-t-transparent rounded-full animate-spin"></div>
             <span className="text-gray-500 font-medium uppercase tracking-widest text-sm">Loading Nexus Data...</span>
          </div>
        ) : esportsData ? (
          <EsportsSection matches={esportsData.matches} standings={esportsData.standings} />
        ) : (
           <div className="text-center py-12 text-gray-500">Failed to load live data. Please try again later.</div>
        )}
      </div>
    </div>
  );
};

const ProfilePage = () => {
  const [player, setPlayer] = useState<PlayerSummary | null>(null);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // In a real app we'd use useParams, but for this demo we'll extract from location hash
  useEffect(() => {
    const fetchPlayer = async () => {
      const parts = window.location.hash.split('/');
      const region = parts[2];
      const name = decodeURIComponent(parts[3] || '');

      if (!name) {
        setError("Summoner name is required");
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        const [profileData, matchData] = await Promise.all([
          geminiService.searchPlayer(name, region),
          geminiService.getMatchHistory(name)
        ]);
        setPlayer(profileData);
        setMatches(matchData);
      } catch (err) {
        console.error(err);
        setError("Could not find the requested summoner.");
      } finally {
        setLoading(false);
      }
    };

    fetchPlayer();
  }, [window.location.hash]);

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-32 flex flex-col items-center justify-center space-y-4">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-[#c8aa6e]/20 border-t-[#c8aa6e] rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-10 h-10 bg-[#c8aa6e]/10 rounded transform rotate-45 border border-[#c8aa6e]/30"></div>
          </div>
        </div>
        <p className="text-[#c8aa6e] font-bold uppercase tracking-widest animate-pulse">Syncing with Rift...</p>
      </div>
    );
  }

  if (error || !player) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-32 text-center">
        <h2 className="text-3xl font-bold text-red-500 mb-4">Error</h2>
        <p className="text-gray-400 mb-8">{error || "Something went wrong."}</p>
        <button 
          onClick={() => window.location.hash = '#/'}
          className="bg-[#c8aa6e] text-[#0a1428] px-6 py-2 rounded font-bold uppercase"
        >
          Return Home
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PlayerStats player={player} />
      <MatchHistory matches={matches} />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <Router>
      <Layout>
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/profile/:region/:name" element={<ProfilePage />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { PlayerSummary, Match, EsportsMatch, Standing } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const geminiService = {
  async searchPlayer(name: string, region: string): Promise<PlayerSummary> {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Search for a League of Legends player named "${name}" in region "${region}". Generate a realistic profile.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
