            <tr>
              <th className="px-6 py-4">Rank</th>
              <th className="px-6 py-4">Summoner</th>
              <th className="px-6 py-4">LP</th>
              <th className="px-6 py-4">Win Rate</th>
              <th className="px-6 py-4">Level</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#1e2328]">
            {loading ? (
              <tr><td colSpan={5} className="text-center py-20 text-gray-500">Updating Rankings...</td></tr>
            ) : players.map((p, i) => (
              <tr 
                key={i} 
                onClick={() => navigate(`/profile/${region}/${p.summonerName}`)}
