              summonerName: { type: Type.STRING },
              lp: { type: Type.NUMBER },
              winRate: { type: Type.NUMBER },
              level: { type: Type.NUMBER }
            },
            required: ["rank", "summonerName", "lp", "winRate", "level"]
          }
        }
      }
    });
    return JSON.parse(response.text);
  }
};

