        </div>
      </div>

      {filteredAndSortedChampions.length === 0 ? (
        <div className="py-20 text-center border border-dashed border-[#1e2328] rounded">
          <p className="text-gray-500 uppercase font-bold tracking-widest">No champions found for this role.</p>
