const ChampionsPage = () => {
  const [champions, setChampions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedChamp, setSelectedChamp] = useState<string | null>(null);

  // Filtering and Sorting State
  const [filterRole, setFilterRole] = useState('All');
  const [sortBy, setSortBy] = useState('name-asc');

  useEffect(() => {
    geminiService.getChampions().then(data => {
      setChampions(data);
      setLoading(false);
    });
  }, []);

  const roles = useMemo(() => {
    const r = new Set<string>(['All']);
    champions.forEach(c => r.add(c.role));
    return Array.from(r);
  }, [champions]);

  const filteredAndSortedChampions = useMemo(() => {
    let result = [...champions];

    // Filter
    if (filterRole !== 'All') {
      result = result.filter(c => c.role === filterRole);
    }

    // Sort
    result.sort((a, b) => {
      switch (sortBy) {
        case 'name-asc':
          return a.name.localeCompare(b.name);
        case 'name-desc':
          return b.name.localeCompare(a.name);
        case 'difficulty-asc':
          return a.difficulty.localeCompare(b.difficulty); // Note: Simple string compare, good enough for "Low/Med/High"
        case 'difficulty-desc':
          return b.difficulty.localeCompare(a.difficulty);
        default:
          return 0;
      }
    });

    return result;
  }, [champions, filterRole, sortBy]);

  if (loading) return <div className="p-20 text-center text-[#c8aa6e] animate-pulse uppercase tracking-widest font-bold">Summoning Champions...</div>;

  return (
    <div className="max-w-7xl mx-auto px-4 py-12">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12">
        <div>
          <h1 className="lol-font text-5xl text-[#c8aa6e] uppercase tracking-tighter mb-2">Champions</h1>
          <p className="text-gray-500 text-sm font-bold uppercase tracking-widest italic">Database of Legend</p>
        </div>

        <div className="flex flex-wrap gap-4">
          {/* Role Filter */}
          <div className="flex flex-col gap-1.5">
            <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest px-1">Filter by Role</span>
            <select 
              value={filterRole}
              onChange={(e) => setFilterRole(e.target.value)}
              className="bg-[#0a1428] border border-[#1e2328] text-[#c8aa6e] px-4 py-2 rounded focus:border-[#c8aa6e] outline-none text-xs font-bold uppercase tracking-widest appearance-none pr-10"
              style={{ backgroundImage: `url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="%23c8aa6e" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>')`, backgroundRepeat: 'no-repeat', backgroundPosition: 'right 10px center' }}
            >
              {roles.map(role => (
                <option key={role} value={role}>{role}</option>
              ))}
            </select>
          </div>

          {/* Sort Control */}
          <div className="flex flex-col gap-1.5">
            <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest px-1">Sort by</span>
            <select 
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
