const ProfilePage = () => {
  const [player, setPlayer] = useState<PlayerSummary | null>(null);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchPlayer = async () => {
      const parts = window.location.hash.split('/');
      const region = parts[2];
      const name = decodeURIComponent(parts[3] || '');

      if (!name) return;

      try {
        setLoading(true);
        const [profileData, matchData] = await Promise.all([
          geminiService.searchPlayer(name, region),
          geminiService.getMatchHistory(name)
        ]);
        setPlayer(profileData);
        setMatches(matchData);
        setError(null);
      } catch (err) {
        console.error(err);
        setError("Could not find the requested summoner.");
      } finally {
        setLoading(false);
      }
    };

    fetchPlayer();
  }, [window.location.hash]);

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-32 flex flex-col items-center justify-center space-y-4">
        <div className="w-20 h-20 border-4 border-[#c8aa6e]/20 border-t-[#c8aa6e] rounded-full animate-spin"></div>
        <p className="text-[#c8aa6e] font-bold uppercase tracking-widest animate-pulse">Syncing with Rift...</p>
      </div>
    );
  }

  if (error || !player) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-32 text-center">
        <h2 className="text-3xl font-bold text-red-500 mb-4 italic">SIGNAL LOST</h2>
        <p className="text-gray-400 mb-8">{error || "Summoner not found in database."}</p>
        <button 
          onClick={() => window.location.hash = '#/'}
          className="bg-[#c8aa6e] text-[#0a1428] px-6 py-2 rounded font-bold uppercase tracking-widest italic active:scale-95 transition-all"
        >
          Back to Terminal
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PlayerStats player={player} />
      <MatchHistory matches={matches} />
    </div>
  );
};

const App: React.FC = () => {
