  const [player, setPlayer] = useState<PlayerSummary | null>(null);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    const fetchPlayer = async () => {
      const parts = window.location.hash.split('/');
      const region = parts[2];
      const name = decodeURIComponent(parts[3] || '');
      if (!name) return;
      try {
        setLoading(true);
        const [profileData, matchData] = await Promise.all([geminiService.searchPlayer(name, region), geminiService.getMatchHistory(name)]);
        setPlayer(profileData);
        setMatches(matchData);
        setError(null);
      } catch (err) { setError("Could not find the requested summoner."); } finally { setLoading(false); }
    };
    fetchPlayer();
  }, [window.location.hash]);
  if (loading) return <div className="max-w-7xl mx-auto px-4 py-32 flex flex-col items-center justify-center space-y-4"><div className="w-20 h-20 border-4 border-[#c8aa6e]/20 border-t-[#c8aa6e] rounded-full animate-spin"></div><p className="text-[#c8aa6e] font-bold uppercase tracking-widest animate-pulse">Syncing with Rift...</p></div>;
  if (error || !player) return <div className="max-w-7xl mx-auto px-4 py-32 text-center"><h2 className="text-3xl font-bold text-red-500 mb-4 italic">SIGNAL LOST</h2><p className="text-gray-400 mb-8">{error || "Summoner not found in database."}</p><button onClick={() => window.location.hash = '#/'} className="bg-[#c8aa6e] text-[#0a1428] px-6 py-2 rounded font-bold uppercase tracking-widest italic active:scale-95 transition-all">Back to Terminal</button></div>;
  return ( <div className="max-w-7xl mx-auto px-4 py-8"><PlayerStats player={player} /><MatchHistory matches={matches} /></div> );
};

const App: React.FC = () => {
  return (
    <Router>
      <Layout>
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/champions" element={<ChampionsPage />} />
          <Route path="/items" element={<ItemsPage />} />
          <Route path="/leaderboards" element={<LeaderboardsPage />} />
          <Route path="/pro-play" element={<ProPlayPage />} />
          <Route path="/login" element={<LoginPage />} />
          <Route path="/profile/:region/:name" element={<ProfilePage />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { geminiService } from '../services/geminiService';
import { Item } from '../types';

interface ItemIconProps {
  itemName: string;
  size?: 'sm' | 'md';
}

const ItemIcon: React.FC<ItemIconProps> = ({ itemName, size = 'md' }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [details, setDetails] = useState<Item | null>(null);
  const [loading, setLoading] = useState(false);
  const [coords, setCoords] = useState({ top: 0, left: 0 });
  const timerRef = useRef<number | null>(null);
  const iconRef = useRef<HTMLDivElement>(null);

  const fetchDetails = async () => {
    if (details || loading) return;
    setLoading(true);
    try {
      const data = await geminiService.getItemDetails(itemName);
      setDetails(data);
    } catch (e) {
      console.error("Failed to load item details", e);
    } finally {
      setLoading(false);
    }
  };

  const handleMouseEnter = () => {
    if (iconRef.current) {
      const rect = iconRef.current.getBoundingClientRect();
      // Position the tooltip above the icon, centered horizontally
      setCoords({
        top: rect.top,
        left: rect.left + rect.width / 2
      });
    }

    timerRef.current = window.setTimeout(() => {
      setIsHovered(true);
      fetchDetails();
    }, 150);
  };

  const handleMouseLeave = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    setIsHovered(false);
  };

  const sizeClasses = size === 'sm' ? 'w-5 h-5' : 'w-7 h-7';

  return (
    <div 
      ref={iconRef}
      className={`relative ${sizeClasses} bg-[#0a1428] border border-gray-800 rounded-sm group cursor-help`}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <img 
        src={`https://picsum.photos/seed/${itemName}/40/40`} 
        alt={itemName} 
        className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity"
      />

      {isHovered && (
        <div 
          className="fixed z-[9999] w-64 md:w-72 p-4 bg-[#0a1428] border border-[#c8aa6e]/50 rounded shadow-2xl pointer-events-none animate-fadeIn backdrop-blur-md"
          style={{
            top: `${coords.top - 10}px`,
            left: `${coords.left}px`,
            transform: 'translate(-50%, -100%)'
          }}
        >
          {/* Tooltip Arrow */}
          <div className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-4 h-4 bg-[#0a1428] border-r border-b border-[#c8aa6e]/50 rotate-45"></div>

          {loading ? (
            <div className="flex items-center justify-center gap-2 py-4">
              <div className="w-4 h-4 border-2 border-[#c8aa6e] border-t-transparent rounded-full animate-spin"></div>
              <span className="text-[10px] text-[#c8aa6e] font-bold uppercase tracking-widest italic">Decrypting Item...</span>
            </div>
          ) : details ? (
            <div className="space-y-2">
              <div className="flex justify-between items-start border-b border-[#1e2328] pb-2">
                <div>
                  <h4 className="text-[#c8aa6e] font-black italic uppercase text-xs tracking-tighter">{details.name}</h4>
                  <div className="flex gap-1 mt-1">
                    {details.tags.slice(0, 2).map(tag => (
                      <span key={tag} className="text-[8px] bg-gray-900 text-gray-500 px-1 py-0.5 rounded border border-gray-800 uppercase font-bold">{tag}</span>
                    ))}
                  </div>
                </div>
                <div className="flex items-center gap-1">
                  <div className="w-2.5 h-2.5 bg-yellow-500 rounded-full border border-yellow-300"></div>
                  <span className="text-yellow-500 font-bold text-[10px]">{details.gold}</span>
                </div>
              </div>

              <div className="text-[10px] text-blue-400 font-bold leading-tight italic py-1">
                {details.stats}
              </div>

              <div className="text-[10px] text-gray-400 leading-relaxed font-medium">
                {details.description}
              </div>
            </div>
          ) : (
             <div className="text-center py-2 text-[10px] text-gray-500 font-bold uppercase tracking-widest">{itemName}</div>
          )}
        </div>
      )}
    </div>
  );
};

export default ItemIcon;
